    ('8e54d502-a3b0-4738-8fdf-c74e6d10d03c'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd3-2026-10-04-s012:8e54d502-a3b0-4738-8fdf-c74e6d10d03c:period_name', 'fields-wd3-2026-10-04-s012 (wd3-derive-period-name): period_start -800 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-800) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (derived, round 0, rule:derived_rule.json)", "decision": "replace", "status": "RULE", "reasoning": "site_type ''Fort'' lies in ''Iron Age''; the rule writes the epoch''s beginning. a fort is an Iron Age or Roman fortification", "value_page": null, "model": null}]'::jsonb),
